using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new List<(string project, string code, string message, string file, int line)>();
build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { proj = tp.Name; break; }
        node = node.Parent as BaseNode;
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? "", e.File ?? "", e.LineNumber));
});

// Collect all warnings 
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { proj = tp.Name; break; }
        node = node.Parent as BaseNode;
    }
    warnings.Add((proj, w.Code ?? "", w.Text ?? ""));
});

Console.WriteLine($"=== ERRORS ({errors.Count} total) ===");
foreach (var g in errors.GroupBy(e => e.project)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

Console.WriteLine($"\n=== WARNINGS ({warnings.Count} total) ===");
foreach (var g in warnings.GroupBy(w => w.project).Take(20)) {
    Console.WriteLine($"\n--- Project: {g.Key} ({g.Count()} warnings) ---");
    foreach (var w in g.Take(10)) {
        Console.WriteLine($"  [{w.code}] {w.message}");
    }
    if (g.Count() > 10) Console.WriteLine($"  ... and {g.Count()-10} more");
}

// Show project dependency info
Console.WriteLine("\n=== PROJECT STRUCTURE ===");
build.VisitAllChildren<Project>(p => {
    if (p.Children.OfType<Error>().Any() || errors.Any(e => e.project == p.Name)) {
        Console.WriteLine($"Project: {p.Name}");
    }
});
EOF

